<template>
  <v-dialog :model-value="modelValue" max-width="980" @update:model-value="emit('update:modelValue', $event)">
    <section class="stats-dialog" role="dialog" aria-labelledby="zalo-stats-title">
      <header class="stats-header"><div><p class="company-name">CÔNG TY TNHH IN ẤN NHÀ YẾN</p><h2 id="zalo-stats-title">Thống kê hoạt động Zalo</h2><p>Theo dõi hoạt động của nick Zalo đang được chọn trong Tin nhắn</p></div><button class="close-button" type="button" aria-label="Đóng thống kê" @click="emit('update:modelValue', false)"><v-icon size="21">mdi-close</v-icon></button></header>
      <div class="stats-body">
        <div class="scope-row">
          <div class="scope-info"><v-avatar size="48" color="#f45d32" class="scope-avatar"><v-img v-if="singleAccount?.avatarUrl" :src="singleAccount.avatarUrl"/><span v-else>{{ accountInitials }}</span></v-avatar><div><strong>{{ scopeTitle }}</strong><span><i/>{{ connectedLabel }}</span></div></div>
          <div class="period-buttons" aria-label="Chọn khoảng thời gian"><button v-for="item in presets" :key="item.key" type="button" :class="{ active: period === item.key }" @click="selectPeriod(item.key)"><v-icon v-if="item.key === 'custom'" size="16">mdi-calendar-blank-outline</v-icon>{{ item.label }}</button></div>
        </div>
        <div v-if="period === 'custom'" class="custom-dates"><label>Từ ngày<input v-model="customFrom" type="date" :max="today"/></label><label>Đến ngày<input v-model="customTo" type="date" :max="today"/></label><button type="button" :disabled="!customFrom || !customTo || customFrom > customTo" @click="loadStatistics">Áp dụng</button></div>
        <div v-if="loading" class="loading-grid" aria-busy="true" aria-label="Đang tải thống kê"><div v-for="i in 6" :key="i" class="skeleton"/></div>
        <div v-else-if="error" class="error-state" role="alert"><v-icon size="28">mdi-alert-circle-outline</v-icon><span>{{ error }}</span><button type="button" @click="loadStatistics">Thử lại</button></div>
        <template v-else>
          <div class="metrics-grid"><article v-for="metric in metrics" :key="metric.label"><div class="metric-heading"><span :class="['metric-icon', metric.tone]"><v-icon size="20">{{ metric.icon }}</v-icon></span><h3>{{ metric.label }}</h3></div><strong>{{ metric.value }}</strong></article></div>
          <section class="chart-card" aria-labelledby="hour-chart-title"><h3 id="hour-chart-title">Số hội thoại theo thời gian trong ngày</h3><p>Lượng hội thoại phát sinh theo từng khung giờ {{ periodDescription }}</p><div v-if="chartMax === 0" class="chart-empty">Chưa có hội thoại phát sinh trong khoảng thời gian này</div><svg v-else class="hour-chart" viewBox="0 0 820 230" role="img" aria-label="Biểu đồ số hội thoại theo giờ"><defs><linearGradient id="zaloChartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#12b8c3" stop-opacity=".25"/><stop offset="1" stop-color="#12b8c3" stop-opacity=".02"/></linearGradient></defs><g v-for="tick in chartTicks" :key="tick.value"><line x1="52" :y1="tick.y" x2="800" :y2="tick.y" class="grid-line"/><text x="42" :y="tick.y + 4" text-anchor="end">{{ tick.value }}</text></g><path :d="areaPath" fill="url(#zaloChartFill)"/><path :d="linePath" class="chart-line"/><text v-for="hour in chartLabels" :key="hour" :x="chartX(hour)" y="220" :text-anchor="hour === 0 ? 'start' : hour === 24 ? 'end' : 'middle'">{{ hour }}h</text></svg></section>
        </template>
      </div>
    </section>
  </v-dialog>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { api } from '@/api/index';
type Period='today'|'yesterday'|'thisMonth'|'lastMonth'|'custom';
type Statistics={scope:'single'|'all';connectedCount:number;accounts:Array<{id:string;displayName?:string|null;phone?:string|null;avatarUrl?:string|null;status:string}>;totals:{sent:number;received:number;total:number;friendRequests:number;unread:number;averageResponseSeconds:number};conversationsByHour:Array<{hour:number;count:number}>};
const props=defineProps<{modelValue:boolean;accountIds:string[]}>();
const emit=defineEmits<{'update:modelValue':[value:boolean]}>();
const period=ref<Period>('today'),loading=ref(false),error=ref(''),stats=ref<Statistics|null>(null),customFrom=ref(''),customTo=ref('');
const presets:Array<{key:Period;label:string}>=[{key:'today',label:'Hôm nay'},{key:'yesterday',label:'Hôm qua'},{key:'thisMonth',label:'Tháng này'},{key:'lastMonth',label:'Tháng trước'},{key:'custom',label:'Tùy chọn'}];
const today=localDate(new Date());
watch(()=>props.modelValue,open=>{if(open)void loadStatistics()});watch(()=>props.accountIds.join(','),()=>{if(props.modelValue)void loadStatistics()});
const singleAccount=computed(()=>stats.value?.accounts.length===1?stats.value.accounts[0]:null);
const scopeTitle=computed(()=>singleAccount.value?.displayName||singleAccount.value?.phone||'Toàn bộ nick Zalo');
const accountInitials=computed(()=>singleAccount.value?.displayName?.trim().slice(0,2).toUpperCase()||'Z');
const connectedLabel=computed(()=>singleAccount.value?(singleAccount.value.status==='connected'?'Đang kết nối':'Đã ngắt kết nối'):`${stats.value?.connectedCount??0}/${stats.value?.accounts.length??0} nick đang kết nối`);
const periodDescription=computed(()=>period.value==='today'?'hôm nay':'trong khoảng thời gian đã chọn');
const metrics=computed(()=>{const t=stats.value?.totals;return[{label:'Tin nhắn đã gửi',value:number(t?.sent),icon:'mdi-arrow-right',tone:'blue'},{label:'Tin nhắn đã nhận',value:number(t?.received),icon:'mdi-arrow-left',tone:'green'},{label:'Tổng tin nhắn',value:number(t?.total),icon:'mdi-message-text-outline',tone:'purple'},{label:'Lời mời kết bạn mới',value:number(t?.friendRequests),icon:'mdi-account-plus-outline',tone:'amber'},{label:'Hội thoại chưa đọc hiện tại',value:number(t?.unread),icon:'mdi-message-badge-outline',tone:'red'},{label:'Thời gian phản hồi trung bình',value:responseTime(t?.averageResponseSeconds??0),icon:'mdi-clock-outline',tone:'cyan'}]});
const chartMax=computed(()=>Math.max(0,...(stats.value?.conversationsByHour.map(r=>r.count)??[0]))),roundedMax=computed(()=>Math.max(1,Math.ceil(chartMax.value/10)*10));
const chartTicks=computed(()=>[1,.67,.33,0].map(r=>({value:Math.round(roundedMax.value*r),y:18+(1-r)*166}))),chartLabels=[0,4,8,12,16,20,24];
const chartPoints=computed(()=>(stats.value?.conversationsByHour??[]).map(r=>({x:chartX(r.hour),y:184-(r.count/roundedMax.value)*166})));
const linePath=computed(()=>chartPoints.value.map((p,i)=>`${i?'L':'M'} ${p.x} ${p.y}`).join(' '));const areaPath=computed(()=>chartPoints.value.length?`${linePath.value} L ${chartPoints.value.at(-1)!.x} 184 L 52 184 Z`:'');
function chartX(hour:number){return 52+(Math.min(hour,24)/24)*748}function selectPeriod(value:Period){period.value=value;if(value!=='custom')void loadStatistics()}
async function loadStatistics(){const range=dateRange();if(!range)return;loading.value=true;error.value='';try{const{data}=await api.get<Statistics>('/chat/statistics',{params:{accountIds:props.accountIds.join(','),from:range.from.toISOString(),to:range.to.toISOString()}});stats.value=data}catch(cause:any){error.value=cause?.response?.data?.error||'Không tải được dữ liệu thống kê'}finally{loading.value=false}}
function dateRange(){const now=new Date(),start=new Date(now),end=new Date(now);start.setHours(0,0,0,0);end.setHours(0,0,0,0);if(period.value==='today')end.setDate(end.getDate()+1);if(period.value==='yesterday')start.setDate(start.getDate()-1);if(period.value==='thisMonth'){start.setDate(1);end.setMonth(end.getMonth()+1,1)}if(period.value==='lastMonth'){start.setMonth(start.getMonth()-1,1);end.setDate(1)}if(period.value==='custom'){if(!customFrom.value||!customTo.value||customFrom.value>customTo.value)return null;const from=new Date(`${customFrom.value}T00:00:00`),to=new Date(`${customTo.value}T00:00:00`);to.setDate(to.getDate()+1);return{from,to}}return{from:start,to:end}}
function localDate(d:Date){return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}function number(value=0){return new Intl.NumberFormat('vi-VN').format(value)}function responseTime(seconds:number){if(!seconds)return'0 giây';if(seconds<60)return`${seconds} giây`;const m=Math.floor(seconds/60),s=seconds%60;return s?`${m}p ${s}s`:`${m} phút`}
</script>

<style scoped>
.stats-dialog{overflow:hidden;border-radius:14px;background:#fff;color:#10244a;font-family:inherit;box-shadow:0 18px 55px rgba(16,36,74,.22)}.stats-header{display:flex;align-items:flex-start;justify-content:space-between;padding:20px 28px 17px;border-bottom:1px solid #e5eaf1}.company-name{margin:0 0 3px;color:#1264c4;font-size:11px;font-weight:800;letter-spacing:.055em}.stats-header h2{margin:0;font-size:23px;line-height:1.25}.stats-header>div>p:last-child{margin:5px 0 0;color:#71809a;font-size:13px}.close-button{display:grid;width:34px;height:34px;border:0;border-radius:50%;place-items:center;background:#f0f4f9;color:#66758d;cursor:pointer}.stats-body{padding:20px 28px 28px}.scope-row{display:flex;align-items:center;justify-content:space-between;gap:18px}.scope-info{display:flex;min-width:210px;align-items:center;gap:12px}.scope-avatar{border:2px solid #1467c9;color:#fff;font-size:13px;font-weight:800}.scope-info strong,.scope-info span{display:block}.scope-info strong{font-size:14px}.scope-info span{margin-top:4px;color:#71809a;font-size:12px}.scope-info i{display:inline-block;width:7px;height:7px;margin-right:7px;border-radius:50%;background:#19a66b}.period-buttons{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:7px}.period-buttons button,.custom-dates button{display:inline-flex;min-height:40px;align-items:center;justify-content:center;gap:5px;padding:0 15px;border:1px solid #2b7bd4;border-radius:8px;background:#4d91dc;color:#fff;font:600 12px inherit;cursor:pointer;transition:.15s}.period-buttons button:hover{background:#2879d2}.period-buttons button.active{border-color:#084e9e;background:#0b5fbd;box-shadow:inset 0 -2px 0 rgba(0,0,0,.13)}.custom-dates{display:flex;align-items:flex-end;justify-content:flex-end;gap:10px;margin-top:12px;padding:12px;border-radius:9px;background:#f4f8fd}.custom-dates label{color:#52627a;font-size:12px}.custom-dates input{display:block;margin-top:5px;padding:7px 9px;border:1px solid #ccd6e4;border-radius:7px;background:#fff;font:inherit}.custom-dates button:disabled{cursor:not-allowed;opacity:.45}.metrics-grid,.loading-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:20px}.metrics-grid article{min-height:112px;padding:16px 18px;border:1px solid #dce5f1;border-radius:10px;background:#fff}.metrics-grid article:nth-child(-n+3){background:#f5f9ff}.metric-heading{display:flex;align-items:center;gap:10px}.metric-heading h3{margin:0;color:#5d6e88;font-size:12px;font-weight:700}.metric-icon{display:grid;width:35px;height:35px;border-radius:50%;place-items:center}.blue{background:#e3efff;color:#1877df}.green{background:#e5f7f2;color:#0e9c83}.purple{background:#efe8ff;color:#7656d8}.amber{background:#fff3dd;color:#e79a19}.red{background:#ffe8ea;color:#ef4b59}.cyan{background:#e6f5ff;color:#1688d4}.metrics-grid article>strong{display:block;margin-top:13px;color:#0c2853;font-size:29px;line-height:1;font-weight:800}.chart-card{margin-top:20px;padding:20px 24px 14px;border:1px solid #dce5ed;border-radius:11px}.chart-card h3{margin:0;font-size:15px}.chart-card>p{margin:5px 0 8px;color:#71809a;font-size:12px}.hour-chart{display:block;width:100%;height:auto}.hour-chart text{fill:#70809a;font:11px inherit}.grid-line{stroke:#e3e9f1}.chart-line{fill:none;stroke:#0eb3bf;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}.chart-empty{display:grid;height:190px;place-items:center;color:#7b879a;font-size:13px}.skeleton{height:112px;border-radius:10px;background:linear-gradient(90deg,#edf2f8 25%,#f7f9fc 50%,#edf2f8 75%);background-size:200% 100%;animation:pulse 1.2s infinite}.error-state{display:flex;min-height:280px;align-items:center;justify-content:center;flex-direction:column;gap:10px;color:#c43e49}.error-state button{padding:7px 13px;border:1px solid currentColor;border-radius:7px;background:#fff;color:inherit;cursor:pointer}@keyframes pulse{to{background-position:-200% 0}}@media(max-width:760px){.stats-header{padding:17px 18px}.stats-body{padding:16px 18px 20px}.scope-row{align-items:flex-start;flex-direction:column}.period-buttons{justify-content:flex-start}.period-buttons button{padding-inline:11px}.metrics-grid,.loading-grid{grid-template-columns:repeat(2,1fr)}.custom-dates{align-items:stretch;flex-direction:column}.chart-card{padding-inline:12px}}@media(max-width:430px){.metrics-grid,.loading-grid{grid-template-columns:1fr}.stats-header h2{font-size:20px}}
</style>
